// AuthServiceHandler is an implementation of the mavio.auth.v1.AuthService service.
type AuthServiceHandler interface {
	// GetAuthInfo tells clients how to sign in.
	GetAuthInfo(context.Context, *v1.GetAuthInfoRequest) (*v1.GetAuthInfoResponse, error)
	// CreateFirstUser sets up a server in standalone mode: it chooses the
	// mode, creates the administrator and signs it in. It fails with
	// FAILED_PRECONDITION once the server's mode is chosen.
	CreateFirstUser(context.Context, *v1.CreateFirstUserRequest) (*v1.CreateFirstUserResponse, error)
	// Login signs a device in with a password, replacing its previous
	// session. Wrong credentials and disabled users fail with
	// UNAUTHENTICATED; a user with TOTP needs its code, and fails with
	// FAILED_PRECONDITION when the right password comes without one. After
	// three failures for a name or from an address, each failure locks them
	// out twice as long as the one before, from a second up to 15 minutes,
	// and sign-ins fail with RESOURCE_EXHAUSTED meanwhile.
	Login(context.Context, *v1.LoginRequest) (*v1.LoginResponse, error)
	// StartPasskeySignIn begins signing in with a passkey at the origin of
	// the request (its Origin header), which must be HTTPS, or HTTP on
	// localhost, at a host name; the ceremony lasts five minutes.
	StartPasskeySignIn(context.Context, *v1.StartPasskeySignInRequest) (*v1.StartPasskeySignInResponse, error)
	// FinishPasskeySignIn signs a device in with the passkey's response,
	// which names its user. A passkey needs no TOTP code; one that does not
	// verify fails with UNAUTHENTICATED.
	FinishPasskeySignIn(context.Context, *v1.FinishPasskeySignInRequest) (*v1.FinishPasskeySignInResponse, error)
	// StartRefresh gives a session's device a nonce to sign for
	// RefreshSession, valid for two minutes. Unknown sessions are
	// UNAUTHENTICATED.
	StartRefresh(context.Context, *v1.StartRefreshRequest) (*v1.StartRefreshResponse, error)
	// RefreshSession issues a new access token for the device's signature of
	// the nonce: Ed25519 over "mavio-session-refresh-v1", a zero byte, the
	// session ID's 16 bytes and the nonce. A wrong signature, a used or
	// expired nonce, a disabled user and a session idle for longer than the
	// server's session_idle_days are UNAUTHENTICATED; the device then signs
	// in again.
	RefreshSession(context.Context, *v1.RefreshSessionRequest) (*v1.RefreshSessionResponse, error)
	// Logout ends the calling session.
	Logout(context.Context, *v1.LogoutRequest) (*v1.LogoutResponse, error)
	// ListSessions lists the calling user's signed-in devices, most recently
	// seen first.
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	// RevokeSession signs one of the calling user's devices out.
	RevokeSession(context.Context, *v1.RevokeSessionRequest) (*v1.RevokeSessionResponse, error)
	// StartQuickConnect begins signing a device in from a signed-in one
	// (Quick Connect): the new device shows the code, a signed-in user
	// enters it with AuthorizeQuickConnect, and the new device, polling
	// GetQuickConnectState, then signs in with LoginWithQuickConnect as that
	// user. The request expires after ten minutes, or one minute after it
	// was authorized.
	StartQuickConnect(context.Context, *v1.StartQuickConnectRequest) (*v1.StartQuickConnectResponse, error)
	// GetQuickConnectState tells whether a request was authorized; unknown
	// and expired requests are NOT_FOUND.
	GetQuickConnectState(context.Context, *v1.GetQuickConnectStateRequest) (*v1.GetQuickConnectStateResponse, error)
	// AuthorizeQuickConnect signs the device waiting with the code in as the
	// calling user.
	AuthorizeQuickConnect(context.Context, *v1.AuthorizeQuickConnectRequest) (*v1.AuthorizeQuickConnectResponse, error)
	// LoginWithQuickConnect gives the authorized device its access token,
	// once.
	LoginWithQuickConnect(context.Context, *v1.LoginWithQuickConnectRequest) (*v1.LoginWithQuickConnectResponse, error)
	// CreateApiKey makes a token an integration calls the API with, as the
	// administrator creating it; the token is returned once. Administrators
	// only.
	CreateApiKey(context.Context, *v1.CreateApiKeyRequest) (*v1.CreateApiKeyResponse, error)
	// ListApiKeys lists every API key. Administrators only.
	ListApiKeys(context.Context, *v1.ListApiKeysRequest) (*v1.ListApiKeysResponse, error)
	// RevokeApiKey deletes an API key. Administrators only.
	RevokeApiKey(context.Context, *v1.RevokeApiKeyRequest) (*v1.RevokeApiKeyResponse, error)
	// ForgotPassword has the password reset plugin chosen in the server
	// settings deliver a PIN to the user, which resets the password within
	// 30 minutes. It answers the same whether or not the user exists.
	ForgotPassword(context.Context, *v1.ForgotPasswordRequest) (*v1.ForgotPasswordResponse, error)
	// ResetPassword sets a new password with the PIN ForgotPassword
	// delivered, and ends the user's sessions.
	ResetPassword(context.Context, *v1.ResetPasswordRequest) (*v1.ResetPasswordResponse, error)
	// GetInvitation describes an invitation link before it is accepted.
	// Unknown, used up and expired invitations are NOT_FOUND.
	GetInvitation(context.Context, *v1.GetInvitationRequest) (*v1.GetInvitationResponse, error)
	// StartInvitationPasskey begins creating the passkey of the member an
	// invitation creates, at the origin of the request as
	// UserService.StartPasskeyRegistration does; AcceptInvitation finishes
	// it.
	StartInvitationPasskey(context.Context, *v1.StartInvitationPasskeyRequest) (*v1.StartInvitationPasskeyResponse, error)
	// AcceptInvitation creates a member with a password or a passkey, or
	// converts the invitation's managed user into one, and signs the device
	// in as it. An invitation used up or expired meanwhile is NOT_FOUND; a
	// taken name is ALREADY_EXISTS; a passkey that does not verify is
	// INVALID_ARGUMENT.
	AcceptInvitation(context.Context, *v1.AcceptInvitationRequest) (*v1.AcceptInvitationResponse, error)
	// ListSwitchableUsers lists the enabled users the calling session may
	// switch to: on a session signed in as the administrator, or switched
	// from one, every user (docs/accounts.md §4.4). Other sessions are
	// PERMISSION_DENIED.
	ListSwitchableUsers(context.Context, *v1.ListSwitchableUsersRequest) (*v1.ListSwitchableUsersResponse, error)
	// SwitchUser makes the calling session the given user's: its access
	// token and refreshes then act as that user, and the session can still
	// switch. A user with a PIN needs it: without one the call is
	// FAILED_PRECONDITION, a wrong one PERMISSION_DENIED, and after three
	// wrong PINs for a user each locks it out twice as long as the one
	// before, as Login does, with RESOURCE_EXHAUSTED meanwhile. Streams the
	// session opened before switching keep their user, so the client opens
	// them again.
	SwitchUser(context.Context, *v1.SwitchUserRequest) (*v1.SwitchUserResponse, error)
	// StartSignIn starts signing a Mavio account in to the server's web UI
	// (docs/accounts.md §6): the server pushes the web UI's authorization
	// request to mavio.dev, signed with its identity key, and returns the
	// page where the account approves it, which sends the browser to the
	// redirect URI with an authorization code for the device key. While the
	// server's mode is unset, or it is unclaimed in mavio.dev mode, signing
	// in claims it (docs/accounts.md §3.2): the account that approves
	// becomes the administrator, and the server learns of it when the
	// account signs in with SignInWithAssertion. It fails with
	// FAILED_PRECONDITION when the server is standalone and UNAVAILABLE when
	// mavio.dev cannot be reached.
	StartSignIn(context.Context, *v1.StartSignInRequest) (*v1.StartSignInResponse, error)
	// SignInWithAssertion signs a device in to a server in mavio.dev mode
	// with a sign-in assertion mavio.dev issued for the server and the
	// device's key, replacing the device's previous session. The device
	// signs, with its key, "mavio-sign-in-assertion-v1", a zero byte and the
	// assertion. A wrong, expired or used assertion, a wrong signature and
	// an account without access to the server fail with UNAUTHENTICATED; a
	// server not in mavio.dev mode fails with FAILED_PRECONDITION. On a
	// server that a sign-in is claiming, it first asks mavio.dev for the
	// account that approved it, and fails with UNAVAILABLE when mavio.dev
	// cannot be reached.
	SignInWithAssertion(context.Context, *v1.SignInWithAssertionRequest) (*v1.SignInWithAssertionResponse, error)
}

